ssize_t read_sound_timer_data(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    struct sound_timer_dev *dev = file->private_data;
    ssize_t bytes_read = 0;
    int ret;

    if (!dev)
        return -EINVAL;

    mutex_lock(&dev->mutex);
    spin_lock_irq(&dev->spinlock);

    if (dev->queue_size == 0) {
        spin_unlock_irq(&dev->spinlock);
        if (file->f_flags & O_NONBLOCK) {
            mutex_unlock(&dev->mutex);
            return -EAGAIN;
        }

        ret = wait_event_interruptible(dev->read_queue_wait, dev->queue_size > 0);
        if (ret) {
            mutex_unlock(&dev->mutex);
            return ret;
        }
        spin_lock_irq(&dev->spinlock);
    }

    bytes_read = min(count, (size_t)dev->queue_size);
    if (copy_to_user(buffer, dev->queue + *offset, bytes_read)) {
        spin_unlock_irq(&dev->spinlock);
        mutex_unlock(&dev->mutex);
        return -EFAULT;
    }

    *offset = (*offset + bytes_read) % dev->queue_capacity;
    dev->queue_size -= bytes_read;
    spin_unlock_irq(&dev->spinlock);
    mutex_unlock(&dev->mutex);

    wake_up_interruptible(&dev->write_queue_wait);

    return bytes_read;
}

ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    ssize_t bytes_read = 0;
    int result;

    spin_lock(&sound_timer_lock);
    mutex_lock(&sound_timer_mutex);

    while (sound_timer_queue_empty()) {
        if (file->f_flags & O_NONBLOCK) {
            result = -EAGAIN;
            goto out;
        }

        if (signal_pending(current)) {
            result = -ERESTARTSYS;
            goto out;
        }

        wait_event_interruptible(sound_timer_wait_queue, !sound_timer_queue_empty());
    }

    while (bytes_read < count && !sound_timer_queue_empty()) {
        char data;
        if (!sound_timer_dequeue(&data)) {
            result = -EFAULT;
            goto out;
        }

        if (copy_to_user(buffer + bytes_read, &data, 1)) {
            result = -EFAULT;
            goto out;
        }

        bytes_read++;
    }

    *offset += bytes_read;
    result = bytes_read;

out:
    mutex_unlock(&sound_timer_mutex);
    spin_unlock(&sound_timer_lock);
    return result;
}

ssize_t read_sound_timer_data(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    ssize_t bytes_read = 0;
    struct sound_timer_dev *dev = file->private_data;
    unsigned long flags;

    if (!dev || !dev->data_queue_head || !buffer || count == 0)
        return -EINVAL;

    spin_lock_irqsave(&dev->spinlock, flags);
    mutex_lock(&dev->mutex);

    while (dev->data_queue_head == dev->data_queue_tail) {
        if (file->f_flags & O_NONBLOCK) {
            mutex_unlock(&dev->mutex);
            spin_unlock_irqrestore(&dev->spinlock, flags);
            return -EAGAIN;
        }

        if (wait_for_interruptible(wait_queue_head_t, !queue_empty)) {
            mutex_unlock(&dev->mutex);
            spin_unlock_irqrestore(&dev->spinlock, flags);
            return -ERESTARTSYS;
        }
    }

    size_t available = dev->data_queue_size - dev->data_queue_head;
    size_t to_read = min(available, count);

    if (copy_to_user(buffer, dev->data_queue + dev->data_queue_head, to_read)) {
        mutex_unlock(&dev->mutex);
        spin_unlock_irqrestore(&dev->spinlock, flags);
        return -EFAULT;
    }

    dev->data_queue_head = (dev->data_queue_head + to_read) % dev->data_queue_size;
    *offset += to_read;
    bytes_read = to_read;

    mutex_unlock(&dev->mutex);
    spin_unlock_irqrestore(&dev->spinlock, flags);

    return bytes_read;
}

