ssize_t read_sound_timer_data(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    ssize_t bytes_read = 0;
    struct sound_timer_dev *dev = file->private_data;
    struct queue_entry *entry = NULL;
    unsigned long flags;
    int ret;

    if (!dev) {
        return -ENODEV;
    }

    mutex_lock(&dev->mutex);
    spin_lock_irqsave(&dev->spinlock, flags);

    while (dev->queue_head == dev->queue_tail) {
        if ((file->f_flags & O_NONBLOCK)) {
            spin_unlock_irqrestore(&dev->spinlock, flags);
            mutex_unlock(&dev->mutex);
            return -EAGAIN;
        }
        if (signal_pending(current)) {
            spin_unlock_irqrestore(&dev->spinlock, flags);
            mutex_unlock(&dev->mutex);
            return -ERESTARTSYS;
        }

        wait_event_interruptible(dev->read_wait,
            dev->queue_head != dev->queue_tail);
    }

    entry = &dev->queue[dev->queue_head];
    bytes_read = min(count, entry->length - dev->read_pos);
    ret = copy_to_user(buffer, entry->data + dev->read_pos, bytes_read);
    if (ret) {
        spin_unlock_irqrestore(&dev->spinlock, flags);
        mutex_unlock(&dev->mutex);
        return -EFAULT;
    }

    dev->read_pos += bytes_read;
    if (dev->read_pos >= entry->length) {
        dev->read_pos = 0;
        dev->queue_head = (dev->queue_head + 1) % QUEUE_SIZE;
    }

    spin_unlock_irqrestore(&dev->spinlock, flags);
    mutex_unlock(&dev->mutex);

    return bytes_read;
}
